proxy:
pid /home/alice/.local/state/ivm-services/nginx/nginx.pid;
error_log stderr warn;
events { worker_connections 1024; }
http {
  include @STORE@;
  access_log off;
  map $http_upgrade $connection_upgrade { default upgrade; "" close; }

  client_body_temp_path /home/alice/.local/state/ivm-services/nginx/body;
  proxy_temp_path /home/alice/.local/state/ivm-services/nginx/proxy;
  server {
  listen 100.64.0.2:8443 ssl;
  listen 127.0.1.1:8443 ssl;
  server_name services.example.test;
  ssl_certificate /var/lib/ivm-services-tls/cert.pem;
ssl_certificate_key /var/lib/ivm-services-tls/key.pem;
ssl_protocols TLSv1.2 TLSv1.3;

  if ($http_host !~* "^services\.example\.test(:8443)?$") { return 421; }
  location / { proxy_pass http://127.0.0.1:8888; proxy_set_header Host $http_host;
proxy_set_header X-Forwarded-Proto $scheme;
proxy_http_version 1.1;
proxy_set_header Upgrade $http_upgrade;
proxy_set_header Connection $connection_upgrade;
proxy_buffering off;
proxy_cache off;
 }
}

  server {
  listen 100.64.0.2:8444 ssl;
  listen 127.0.1.1:8444 ssl;
  server_name services.example.test;
  ssl_certificate /var/lib/ivm-services-tls/cert.pem;
ssl_certificate_key /var/lib/ivm-services-tls/key.pem;
ssl_protocols TLSv1.2 TLSv1.3;

  if ($http_host !~* "^services\.example\.test(:8444)?$") { return 421; }
  client_max_body_size 16m;
location / { proxy_pass http://127.0.0.1:11235; proxy_set_header Host $http_host;
proxy_set_header X-Forwarded-Proto $scheme;
proxy_http_version 1.1;
proxy_set_header Upgrade $http_upgrade;
proxy_set_header Connection $connection_upgrade;
proxy_buffering off;
proxy_cache off;
 proxy_read_timeout 1800s; }

}

  server {
  listen 100.64.0.2:8445 ssl;
  listen 127.0.1.1:8445 ssl;
  server_name services.example.test;
  ssl_certificate /var/lib/ivm-services-tls/cert.pem;
ssl_certificate_key /var/lib/ivm-services-tls/key.pem;
ssl_protocols TLSv1.2 TLSv1.3;

  if ($http_host !~* "^services\.example\.test(:8445)?$") { return 421; }
  root @STORE@;
location / { try_files $uri $uri/ =404; add_header Cache-Control no-cache; add_header Referrer-Policy no-referrer always; add_header X-Content-Type-Options nosniff always; }
location /api/ { proxy_pass http://127.0.0.1:47328; proxy_set_header Host $http_host;
proxy_set_header X-Forwarded-Proto $scheme;
proxy_http_version 1.1;
proxy_set_header Upgrade $http_upgrade;
proxy_set_header Connection $connection_upgrade;
proxy_buffering off;
proxy_cache off;
 client_max_body_size 2m; proxy_intercept_errors on; error_page 502 504 =503 @unavailable; }
location /mcp { proxy_pass http://127.0.0.1:47328; proxy_set_header Host $http_host;
proxy_set_header X-Forwarded-Proto $scheme;
proxy_http_version 1.1;
proxy_set_header Upgrade $http_upgrade;
proxy_set_header Connection $connection_upgrade;
proxy_buffering off;
proxy_cache off;
 proxy_read_timeout 300s; proxy_intercept_errors on; error_page 502 504 =503 @unavailable; }
location @unavailable { default_type application/json; add_header Cache-Control no-store always; return 503 '{"error":{"code":"unavailable","message":"service unavailable"}}'; }

}

  server {
  listen 100.64.0.2:8446 ssl;
  listen 127.0.1.1:8446 ssl;
  server_name services.example.test;
  ssl_certificate /var/lib/ivm-services-tls/cert.pem;
ssl_certificate_key /var/lib/ivm-services-tls/key.pem;
ssl_protocols TLSv1.2 TLSv1.3;

  if ($http_host !~* "^services\.example\.test(:8446)?$") { return 421; }
  # Suppress native request-line errors, which can contain capability URLs.
error_log /dev/null;
client_max_body_size 4m;
client_header_buffer_size 4k;
large_client_header_buffers 4 8k;
location / { proxy_pass http://127.0.0.1:47329; proxy_set_header Host $http_host;
proxy_set_header X-Forwarded-Proto $scheme;
proxy_http_version 1.1;
proxy_set_header Upgrade $http_upgrade;
proxy_set_header Connection $connection_upgrade;
proxy_buffering off;
proxy_cache off;
 proxy_request_buffering off; proxy_read_timeout 30s; proxy_send_timeout 30s; }

}


  server {
  listen 100.64.0.2:8447 ssl;
  listen 127.0.1.1:8447 ssl;
  server_name services.example.test;
  ssl_certificate /var/lib/ivm-services-tls/cert.pem;
ssl_certificate_key /var/lib/ivm-services-tls/key.pem;
ssl_protocols TLSv1.2 TLSv1.3;

  if ($http_host !~* "^services\.example\.test(:8447)?$") { return 421; }
  # Trusted, Tailscale-only static hosting. Reads (GET/HEAD) are open on the
# tailnet; writes (PUT/DELETE/MKCOL) require the publish token via basic auth.
# Before the token is provisioned the htpasswd file is absent and nginx fails
# writes closed (403).
root /home/alice/.local/state/ivm-services/www;
autoindex on;
autoindex_format json;
client_max_body_size 1g;
location / {
  dav_methods PUT DELETE MKCOL;
  create_full_put_path on;
  limit_except GET HEAD {
    auth_basic "ivm publish";
    auth_basic_user_file /home/alice/.local/state/ivm-services/credentials/static.htpasswd;
  }
}
# Read-only JSON directory listing that ignores index.html, for `ivm-publish ls`.
location /.ivm-list/ {
  alias /home/alice/.local/state/ivm-services/www/;
  index ___none___;
  autoindex on;
  autoindex_format json;
}

}

}

setup:
#!@STORE@
set -euo pipefail
umask 077
@STORE@ -p /home/alice/.local/state/ivm-services/{credentials,nginx,crawl4ai/{home,cache,outputs},www}
@STORE@ -p /home/alice/.local/state/ivm-services/{postgres-socket,backups}

# nginx recreates its request-body/proxy temp dirs on start; drop any left
# non-user-owned (e.g. by a root `nginx -t`, which chowns absolute *_temp_path
# dirs to nginx's compiled-in user) so the user worker can write them.
for d in /home/alice/.local/state/ivm-services/nginx/body /home/alice/.local/state/ivm-services/nginx/proxy; do
  if [ -e "$d" ] && [ ! -O "$d" ]; then @STORE@ -rf "$d"; fi
done
@STORE@ @STORE@ /home/alice/.local/state/ivm-services/credentials \
  --haystack-agent-file /run/secrets/ivm-haystack-agent-token \
  --manure-agent-file /run/secrets/ivm-manure-agent-token
# Generate the nginx basic-auth file for static publishing from the agenix token.
if [ -r /run/secrets/ivm-static-publish-token ]; then
  hash="$(@STORE@ passwd -apr1 -stdin <<<"$(</run/secrets/ivm-static-publish-token)")"
  @STORE@ 'publish:%s\n' "$hash" > /home/alice/.local/state/ivm-services/credentials/static.htpasswd.tmp
  @STORE@ -f /home/alice/.local/state/ivm-services/credentials/static.htpasswd.tmp /home/alice/.local/state/ivm-services/credentials/static.htpasswd
fi
